import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/** The nearest ancestor that scrolls vertically, or null for the page. */
export function scrollParent(element: HTMLElement): HTMLElement | null {
  for (let node = element.parentElement; node && node !== document.body; node = node.parentElement) {
    const { overflowY } = getComputedStyle(node);
    if ((overflowY === "auto" || overflowY === "scroll") && node.scrollHeight > node.clientHeight) return node;
  }
  return null;
}

/** The visible band of a scroller in viewport coordinates: its top edge and height (the window when null). */
export function viewOf(scroller: HTMLElement | null) {
  if (!scroller) return { top: 0, height: window.innerHeight };
  return { top: scroller.getBoundingClientRect().top + scroller.clientTop, height: scroller.clientHeight };
}

"use client";
import { ArrowUp } from "lucide-react";
import { useEffect, useRef, useState, type ComponentProps } from "react";
import { cn } from "./lib/cn";
import { scrollParent } from "./lib/scroll-view";
import "./scroll-top-ring.css";

export type ScrollTopRingProps = Omit<ComponentProps<"button">, "children"> & {
  /** Pixels scrolled before the button appears. */
  threshold?: number;
  label?: string;
  /** The element that receives focus after the jump, by id; the top of the content when not given. */
  focusTarget?: string;
};

/**
 * A back-to-top button whose ring fills as you read. It springs in once you have scrolled past the threshold, stays
 * in the corner of whatever scrolls (the page or a panel), and returns you to the top with focus at the start of
 * the content. Place it last inside the scrolling content. Under reduced motion it appears without the spring and
 * the jump is instant.
 */
export function ScrollTopRing({ threshold = 400, label = "Back to top", focusTarget, className, onClick, ...props }: ScrollTopRingProps) {
  const button = useRef<HTMLButtonElement>(null);
  const ring = useRef<SVGCircleElement>(null);
  const [shown, setShown] = useState(false);

  useEffect(() => {
    const el = button.current;
    if (!el) return;
    const scroller = scrollParent(el);
    let frame = 0;
    const update = () => {
      frame = 0;
      const top = scroller ? scroller.scrollTop : scrollY;
      const room = scroller ? scroller.scrollHeight - scroller.clientHeight : document.documentElement.scrollHeight - innerHeight;
      setShown(top > threshold);
      ring.current?.style.setProperty("--str-p", String(room > 0 ? Math.min(1, top / room) : 0));
    };
    const schedule = () => (frame ||= requestAnimationFrame(update));
    const target = scroller ?? window;
    schedule();
    target.addEventListener("scroll", schedule, { passive: true });
    return () => {
      cancelAnimationFrame(frame);
      target.removeEventListener("scroll", schedule);
    };
  }, [threshold]);

  return (
    <button
      ref={button}
      type="button"
      aria-label={label}
      data-slot="scroll-top-ring"
      data-shown={shown ? "" : undefined}
      tabIndex={shown ? undefined : -1}
      className={cn(className)}
      onClick={(event) => {
        onClick?.(event);
        const scroller = scrollParent(event.currentTarget);
        const still = matchMedia("(prefers-reduced-motion: reduce)").matches;
        (scroller ?? window).scrollTo({ top: 0, behavior: still ? "auto" : "smooth" });
        const goal = (focusTarget && document.getElementById(focusTarget)) || (scroller ?? document.body).querySelector<HTMLElement>("h1, h2, h3, h4, h5, h6");
        if (goal) {
          if (!goal.hasAttribute("tabindex")) goal.setAttribute("tabindex", "-1");
          goal.focus({ preventScroll: true });
        }
      }}
      {...props}
    >
      <svg viewBox="0 0 44 44" aria-hidden="true">
        <circle data-slot="str-track" cx={22} cy={22} r={20} />
        <circle ref={ring} data-slot="str-fill" cx={22} cy={22} r={20} pathLength={1} />
      </svg>
      <ArrowUp aria-hidden="true" />
    </button>
  );
}

/* scroll-top-ring.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Scroll top ring: sticky in the scroller's corner; the ring is the reading progress. */
  [data-slot="scroll-top-ring"] { position: sticky; bottom: 16px; z-index: 5; display: grid; place-items: center; width: 44px; height: 44px; margin: 0 16px 0 auto; padding: 0; border: 0; border-radius: 50%; background: var(--background); color: var(--foreground); box-shadow: var(--shadow-overlay); cursor: pointer; opacity: 0; scale: 0.6; translate: 0 12px; pointer-events: none; transition: opacity var(--duration-normal) var(--ease-out), scale var(--duration-travel) var(--ease-settle), translate var(--duration-travel) var(--ease-settle); }
  [data-slot="scroll-top-ring"][data-shown] { opacity: 1; scale: 1; translate: 0 0; pointer-events: auto; }
  [data-slot="scroll-top-ring"] svg { position: absolute; inset: 0; width: 100%; height: 100%; rotate: -90deg; }
  [data-slot="scroll-top-ring"] circle { fill: none; stroke-width: 2.5; }
  [data-slot="scroll-top-ring"] [data-slot="str-track"] { stroke: var(--border); }
  [data-slot="scroll-top-ring"] [data-slot="str-fill"] { stroke: var(--foreground); stroke-linecap: round; stroke-dasharray: var(--str-p, 0) 1; transition: stroke-dasharray 0.12s linear; }
  [data-slot="scroll-top-ring"] > svg + svg { position: static; width: 18px; height: 18px; rotate: none; }
  @media (hover: hover) { [data-slot="scroll-top-ring"][data-shown]:hover > svg + svg { translate: 0 -2px; transition: translate var(--duration-normal) var(--ease-settle); } }
  [data-slot="scroll-top-ring"]:focus-visible { outline: 2px solid var(--ring); outline-offset: 3px; }
  @media (prefers-reduced-motion: reduce) {
    [data-slot="scroll-top-ring"], [data-slot="scroll-top-ring"] [data-slot="str-fill"] { transition: none; }
  }
}
